-- 2026-10-16 まさ指示: 太陽光・出荷待ち回収と年産10,000Lの小規模比較。
-- データのみ。変更前の指紋で停止する。一度適用した後の再実行は禁止。
begin;
select set_config('amd.cost_change_reason','2026-10-16 まさ指示: 太陽光主体・出荷待ち回収・小規模のユニットエコノミクス比較',true);
do $$ begin
 if (select md5(to_jsonb(t)::text) from project_cost_models t where cost_model_id='cm_p21_fuel_260914') is distinct from 'adcc8fbc8c5835ca03794dc747cc9faa' then raise exception 'fuel model changed: cm_p21_fuel_260914'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_assumptions t where cost_assumption_id='caf_business_annual_volume') is distinct from '2a78bf8fadc1d76ff8031d4a8ee593a2' then raise exception 'fuel model changed: caf_business_annual_volume'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_assumptions t where cost_assumption_id='caf_lipid_secretion') is distinct from '31f4a733e368dbcc1fb3d00d514e8a84' then raise exception 'fuel model changed: caf_lipid_secretion'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_notes t where cost_note_id='cnf_caveat_line') is distinct from 'ef4348bcdd39e15ff46bf78d8b9a28e5' then raise exception 'fuel model changed: cnf_caveat_line'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_notes t where cost_note_id='cnf_guide') is distinct from '72c0d2409e261ca898e082a7f8211e42' then raise exception 'fuel model changed: cnf_guide'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_notes t where cost_note_id='cnf_caveat_biomass') is distinct from '1eecdab69098ea401ddb2737775b86d5' then raise exception 'fuel model changed: cnf_caveat_biomass'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_notes t where cost_note_id='cnf_caveat_secreting') is distinct from 'ff80152b9a316ac6c1116a6de512570c' then raise exception 'fuel model changed: cnf_caveat_secreting'; end if;
 if exists(select 1 from project_cost_assumptions where cost_model_id='cm_p21_fuel_260914' and role_key like 'fuel_%') then raise exception 'operating assumptions already exist'; end if;
end $$;
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_fuel_light_source','cm_p21_fuel_260914','OP1','光と培養の使い方','光源',null,'sunlight','','H','仮置き','AMD（内部）',true,'fuel_light_source','2026-10-16 まさの方針に基づく比較用の前提。太陽光主体ではLED電力・照明器具を外し、年間生産性の比率を掛ける。保温・循環は維持する。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',100,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_fuel_culture_source','cm_p21_fuel_260914','OP2','光と培養の使い方','培養の使い方',null,'inventory','','H','仮置き','AMD（内部）',true,'fuel_culture_source','2026-10-16 まさの方針に基づく比較用の前提。出荷待ちの培養液から分泌分を回収する。出荷量・品質・出荷日を維持する仮説。専用培養と切り替えて比較する。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',101,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_fuel_equipment_sizing','cm_p21_fuel_260914','OP3','光と培養の使い方','設備とロットの数え方',null,'whole','','H','仮置き','AMD（内部）',true,'fuel_equipment_sizing','2026-10-16 まさの方針に基づく比較用の前提。小規模は必要な設備を最低1基、分析・出荷を最低1回で計上する。量産の比例配賦は比較用。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',102,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_sunlight_productivity_ratio','cm_p21_fuel_260914','OP4','光と培養の使い方','太陽光での年間生産性（人工照明比）',50,null,'%','H','仮置き','AMD（内部）',true,'sunlight_productivity_ratio','2026-10-16 まさの方針に基づく比較用の前提。50%は昼夜・季節・天候を含む比較用の仮値。日照時間だけで確定しない。適用は0〜100%。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',103,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_sunlight_capex','cm_p21_fuel_260914','OP5','光と培養の使い方','太陽光利用の追加設備・工事',null,null,'円','H','仮置き','AMD（内部）',true,'sunlight_capex','2026-10-16 まさの方針に基づく比較用の前提。透明閉鎖槽への変更、温調、受光・遮光、設置工事等の追加投資。既存明細に計上済みの費用と重複させない。空欄は未見積。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',104,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_sunlight_life_years','cm_p21_fuel_260914','OP6','光と培養の使い方','太陽光利用の追加設備の耐用年数',10,null,'年','H','仮置き','AMD（内部）',true,'sunlight_life_years','2026-10-16 まさの方針に基づく比較用の前提。10年は償却の仮値。設備の見積と更新周期に合わせる。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',105,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_sunlight_opex_annual','cm_p21_fuel_260914','OP7','光と培養の使い方','太陽光利用の追加維持費',null,null,'円/年','H','仮置き','AMD（内部）',true,'sunlight_opex_annual','2026-10-16 まさの方針に基づく比較用の前提。敷地、夜間維持、冷却、清掃など既存明細との差額。空欄は未見積。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',106,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_inventory_volume_m3','cm_p21_fuel_260914','OP8','光と培養の使い方','出荷待ちの培養液量（同時に使える量）',10,null,'m³','H','仮置き','AMD（内部）',true,'inventory_volume_m3','2026-10-16 まさの方針に基づく比較用の前提。10m³は操作確認用の仮値。同じ待ち期間に回収へ使える実在庫量を入れる。並行する槽は合計し、出荷済みや排水使用後の菌体を含めない。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',107,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_inventory_wait_days','cm_p21_fuel_260914','OP9','光と培養の使い方','1回の出荷待ち日数',3,null,'日/回','H','仮置き','AMD（内部）',true,'inventory_wait_days','2026-10-16 まさの方針に基づく比較用の前提。3日は操作確認用の仮値。出荷を遅らせず回収できる期間。年間回数との積は培養稼働日数を上限にする。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',108,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_inventory_batches_year','cm_p21_fuel_260914','OP10','光と培養の使い方','年間の出荷待ち回数',100,null,'回/年','H','仮置き','AMD（内部）',true,'inventory_batches_year','2026-10-16 まさの方針に基づく比較用の前提。100回は操作確認用の仮値。同じ培養液量を何回分利用できるか。待ち日数との積が稼働日数を超える場合は上限と警告を表示する。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',109,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_inventory_incremental_annual','cm_p21_fuel_260914','OP11','光と培養の使い方','分泌回収による追加費用・出荷影響',null,null,'円/年','H','仮置き','AMD（内部）',true,'inventory_incremental_annual','2026-10-16 まさの方針に基づく比較用の前提。追加の品質管理、株の維持、生産遅延・不良・菌体損失の補償など既存明細にない差額。既存の分泌用溶媒・閉鎖系設備は明細で別計上。空欄は未見積。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',110,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_inventory_common_allocation_annual','cm_p21_fuel_260914','OP12','光と培養の使い方','共通培養費の燃料側への配賦',0,null,'円/年','H','仮置き','AMD（内部）',true,'inventory_common_allocation_annual','2026-10-16 まさの方針に基づく比較用の前提。追加採算の比較として0円を仮置き。排水処理側の費用が消える意味ではない。排水処理事業が共通費を回収できること、全社合計で一度だけ計上することを別途確認する。 確かめ方: 同じ株・槽で年間回収量と追加支出、出荷量・品質・日付への影響を照合する。','amd_internal',111,null,null);
update project_cost_assumptions set value=10000,label='年間の燃料目標量',note='2026-10-16 まさ指定の年間10,000Lを仮置き。100・1,000・10,000Lを比較する。出荷待ち方式の実生産量は在庫と待ち期間から出した回収可能量が上限。確かめ方: 実在庫・年間の供給計画・設備と回収量を照合する。',updated_at=now() where cost_assumption_id='caf_business_annual_volume';
update project_cost_assumptions set value_text='on',note='2026-10-16: 太陽光主体で、出荷待ちの生きた菌体から脂肪酸分泌分を回収する仮説を最初に表示する。分泌株を使わない場合は出荷待ちの分泌回収を使えない。分泌速度と工程収率は従来の文献に基づく仮定を保持し、対象株の確認済み性能とは扱わない。確かめ方: 回収量と出荷量・品質・排水処理性能の両立を同じ株で実測する。',updated_at=now() where cost_assumption_id='caf_lipid_secretion';
update project_cost_models set title='燃料のコスト試算',version_label='261016 小規模・太陽光・出荷待ち',summary_md='燃料1Lあたりの原価を、小規模の設備・作業・生産量から比較する。光源は太陽光主体／人工照明、培養は出荷待ちからの分泌回収／燃料専用で切り替える。年間の目標は10,000Lの仮置き。出荷待ち回収では在庫と待ち時間から回収可能量を出し、実生産量を上限内に収める。設備・出荷・分析は1基・1回単位で計上し、量産の比例配賦も比較できる。小型設備費と屋外での生産性は未実測・未見積で、操作確認用の仮値を含む。保存するのは入力条件で、結果は毎回計算する。',system_scope_md='対象は船舶向け等を想定したバイオディーゼル成分FAME。SAFへの加工は含まない。太陽光主体ではLEDの電力と器具を外し、人工照明に対する年間生産性比率を適用する。保温・循環・回収の運転費は残す。出荷待ち方式は同時に使える培養液量×年間の待ち期間×分泌速度から供給可能量を出し、回収・反応・精製を通した量と目標量の小さい方を実生産量とする。共通培養費は年額配賦で扱い、分泌株専用費と追加費用を計上する。出荷量・品質・日付を維持できることは未確認。使用済み菌体は対象外。小規模設備・天候・温度・日照の実測と見積を得て前提を更新する。売価200円/Lは従来の計画仮値。',updated_at=now() where cost_model_id='cm_p21_fuel_260914';
update project_cost_notes set title='専用培養と出荷待ち回収の費用範囲',body_md='燃料専用で培養する場合は培養費を全額計上する。出荷待ちから回収する場合は、共通の培養設備・原料・作業を再計上せず、分泌株専用の溶媒・回収・閉鎖系設備と、入力した追加費用・共通費配賦を計上する。排水処理側の費用が消える意味ではない。出荷前の菌体だけを対象とし、排水や金属回収に使用した菌体を燃料原料へ回さない。' where cost_note_id='cnf_caveat_line';
update project_cost_notes set title='小規模での採算の見方',body_md='光源（太陽光主体／人工照明）と培養の使い方（出荷待ちから回収／燃料専用）を切り替える。最初の年間目標は10,000Lの仮置きで、100・1,000・10,000Lの比較ボタンでも変更できる。出荷待ちは培養液量・待ち日数・年間回数から回収可能量を算定し、実生産量は目標との小さい方とする。設備・分析・出荷は1基・1回単位で計上する。小型設備の見積に合わせて能力・金額・作業回数を変更する。空欄の追加費用は未見積として表示する。操作は試算で、正本への保存は編集権限がある人だけが保存ボタンから行う。' where cost_note_id='cnf_guide';
update project_cost_notes set title='共通費・追加費と小規模設備の見積',body_md='分泌回収の追加採算と全社の採算を分ける。出荷待ち回収では共通培養費の配賦を年額で入力できる。0円の仮置きは排水処理側で共通費を回収できる場合の比較条件。培養・回収・燃料化の既存明細は従来の設備を参照しており、小型設備の見積ではない。整数設備で大きな費用が出る場合は設備能力・設備費・作業頻度を現実の小型設計へ置き換える必要がある。量産の端数配賦を初期投資額として使わない。' where cost_note_id='cnf_caveat_biomass';
update project_cost_notes set title='太陽光・出荷待ち回収の未確認条件',body_md='太陽光での年間生産性50%、出荷待ち10m³・3日・年100回は操作確認用の仮値。対象株の屋外での分泌速度、夜間と冬季の維持、回収を続けた後の排水処理性能・出荷品質は未実証。屋外設備・敷地・維持費と出荷への影響は未見積のまま。空欄の費用を含まない表示原価だけで採算成立を確定しない。太陽光を使う場合も、必要な閉鎖系の管理を維持する。' where cost_note_id='cnf_caveat_secreting';
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_op_fuel_plant_capex_override','cm_p21_fuel_260914','OP13','燃料化設備','燃料化設備1系列の見積総額（上書き）',null,null,'円/系列','H','仮置き','AMD（内部）',true,'fuel_plant_capex_override','2026-10-16 小規模の燃料化設備の見積総額。空欄は従来の大規模設備の参考値。入力すると選んだ委託/自社構成の設備投資と、初期投資比率で持つ保守費を同率で置き換える。設備能力・年間運転回数・工数は別に入力する。確かめ方: 同じ工程範囲・処理能力・付帯工事・出荷設備を含むメーカー見積と照合する。','amd_internal',113,null,null);
commit;
